'et.d_s_welcome' => 'Вашият достъп до портала на Golden A/S',
'et.d_b_welcome' => "Уважаеми/а {name},\n\nВашият профил в портала на Golden A/S е готов. Моля, следвайте тези три стъпки.\n\n1. ПЪРВО ВЛИЗАНЕ\n   Отворете {url} и влезте с вашия e-mail {email} и временната парола, която ви даваме отделно (по телефона или с второ съобщение — никога в този e-mail).\n\n2. СМЯНА НА ПАРОЛАТА\n   След първото влизане натиснете аватара си горе вдясно (Моят профил) и задайте своя парола в полето Нова парола: най-малко 10 знака, неизползвана другаде.\n\n3. ВКЛЮЧВАНЕ НА ДВУФАКТОРНО УДОСТОВЕРЯВАНЕ (2FA)\n   В Моят профил › Двуфакторно удостоверяване сканирайте QR кода с приложение authenticator (Microsoft Authenticator, Google Authenticator, Authy, …) и въведете 6-цифрения код за потвърждение. Оттук нататък всяко влизане изисква и кода от приложението.\n\nПет грешни пароли блокират профила за 15 минути; ако не можете да влезете, отговорете на този e-mail и ще го отблокираме или ще нулираме паролата.\n\n{signature}",
