'eng.budget_hint' => 'Бюджет = човекочасове, планирани при поръчката. Допълнителни часове се добавят само чрез одобрена заявка. Оставете празно за секции извън обхвата.',
'eng.rules' => 'Изпълнено % = (тегло на завършените резултати + отчетени часове по отворена работа, с таван) ÷ (бюджет + одобрени допълнителни). Използвано % = отчетени ÷ бюджет — над 100 % секцията е над съгласувания бюджет; щрихованата част на лентата е одобреното допълнение. При 90 % от допустимите часове секцията става кехлибарена; над тях тя е превишена и новите инженерни часове се блокират, докато не бъдат одобрени допълнителни часове или секцията не бъде обявена за завършена.',
