/* ---- R47-002 ---- */
'eng.settings' => 'Секции на етапите',
'eng.settings_lede' => 'Секциите на процесната линия с бюджет в часове — Инженеринг (Електро, Автоматизация, Механика, UI/UX, IT), Производство, Обект и монтаж, HAT / SAT, Пускане в експлоатация — и дисциплините, които ги захранват. Бюджетът на една секция е бюджетираните часове на нейните дисциплини в Бюджет и действително на подпроекта; действителните ѝ часове са часовете на същите дисциплини, записани на този етап. Един източник — съгласуван с клиента; одобрените допълнителни часове се показват над него, никога не се добавят към него.',
'eng.map_title' => 'Матрица дисциплина × секция',
'eng.map_hint' => 'Отбележете секциите, които всяка дисциплина захранва. Инженерните дисциплини захранват една инженерна секция; монтажник захранва Обект и монтаж и HAT / SAT; сервизен инженер или инженер по автоматизация — HAT / SAT и Пускане в експлоатация. Дисциплина, която захранва няколко секции, получава по една бюджетна клетка за секция в Бюджет и действително, а етапът, избран на реда в графика за часове, определя къде се броят часовете ѝ. Дисциплините ръководство и продажби остават без съответствие.',
'eng.map_none' => '— не е инженеринг',
'eng.map_save_hint' => 'Прилага се незабавно за всеки подпроект (бюджетите, действителните стойности и етапът „Инженеринг“ се преизчисляват от съответствието).',
'eng.sec_title' => 'Секции',
'eng.sec_code' => 'Код',
'eng.sec_mapped' => 'Дисциплини',
'eng.sec_add' => 'Добави секция',
