'hra.welcome_title' => 'Здравейте, {n}',
'hra.welcome_1' => 'Този асистент събира данните на картона ви на служител в шест кратки стъпки. Всяко поле е предварително попълнено с това, което HR има днес: потвърдете, коригирайте или оставете. Можете да спрете по всяко време и да продължите по-късно — и от телефона си.',
'hra.privacy_title' => 'Как обработваме данните ви',
'hra.privacy_1' => 'Администратор: Golden Automation Systems (Sistimata Ischyos ATEE), Kiou 5, Keratsini — за италианския клон GOLDEN AS ITALIAN. Цел: водене на личното досие, изисквано от трудовото, осигурителното и данъчното законодателство, и връзка с вас или с лицето за спешни случаи. Правно основание: трудовият договор и законовите задължения на работодателя.',
'hra.privacy_2' => 'Въведеното тук се пази във временна област, докато HR го одобри; идентификационните номера (AMKA, ДДС, лична карта, паспорт, IBAN) са криптирани там и се четат само от HR. Получатели: HR, Owner и, за ведомостта, счетоводителят на фирмата. Срок: временните данни се изтриват 90 дни след решението; картонът следва срока на личното досие.',
'hra.privacy_3' => 'Вашите права: достъп, коригиране (чрез този асистент), изтриване и ограничаване, където законът позволява, и жалба до Гръцкия орган за защита на данните (dpa.gr). Въпроси: HR › Съобщения с HR.',
