'et.d_b_po_chase' => "Уважаеми господа,\n\nотносно {doc} молим да потвърдите състоянието на поръчката ни: готова за изпращане стока, дата на изпращане, спедитор и номер за проследяване, както и неизпълнените позиции с очакваната дата.\n\nДоставката е свързана с график на кораб; молим незабавно да ни уведомите за всяко закъснение.\n\nС уважение,\n{user}\n{branch}",
'et.d_s_ncr' => "Несъответствие по поръчка {no}",
'et.d_b_ncr' => "Уважаеми господа,\n\nпри получаване на стоката по {doc} установихме несъответствията, описани в приложения доклад (количество, повреда или отклонение от поръчката). Молим в три работни дни да потвърдите начина на уреждане — замяна, кредитно известие или ремонт — и датата.\n\nНесъответстващите артикули се съхраняват в склада ни на ваше разположение.\n\nС уважение,\n{user}\n{branch}",
'et.d_s_remittance' => "Известие за плащане — {branch}",
'et.d_b_remittance' => "Уважаеми господа,\n\nприложено изпращаме известието за плащане по {doc}. Сумата е преведена по сметката от вашата фактура; молим да я отнесете към изброените фактури и да ни изпратите потвърждение.\n\nС уважение,\n{user}\n{branch}",
'em.template' => "Шаблон",
'em.find_ph' => "Търсене на лице в Контакти — име, e-mail или фирма…",
