'rc.ev_mail_intro' => 'Благодарим Ви за кандидатурата за позицията „{vacancy}“. Бихме искали да Ви поканим на следващата стъпка от нашия процес на подбор:',
'rc.ev_mail_outro' => 'Моля, отговорете на този имейл, за да потвърдите или да предложите друго време. Интервюто следва нашето структурирано оценяване: технически познания, морски опит, решаване на проблеми, нагласа за учене, дългосрочна ангажираност и работа в екип.',
'rc.ev_mail_shortlisted' => 'Добри новини — кандидатурата Ви за „{vacancy}“ е предварително одобрена. Скоро ще се свържем с Вас за интервю.',
'rc.ev_mail_offer' => 'С удоволствие Ви съобщаваме, че след интервютата Ви за „{vacancy}“ желаем да Ви направим оферта. Нашият HR екип ще се свърже с Вас с подробностите.',
'rc.ev_mail_rejected' => 'Благодарим за времето, което отделихте за кандидатурата си за „{vacancy}“. След внимателна оценка този път няма да продължим. Данните Ви се изтриват автоматично след шест месеца, освен ако не поискате да останете в нашия резерв от таланти.',
'rc.ev_notify_status' => 'Уведоми кандидата по имейл за това състояние (одобрен / оферта / отхвърлен)',
'rc.ev_ranking' => 'Класиране на кандидатите',
'rc.ev_ranking_hint' => 'Първо средната оценка (0–100), после резултатът от въпросника. Кликнете върху кандидат, за да отворите картата.',
'rc.ev_criteria' => 'Критерии за оценяване',
'rc.ev_criteria_hint' => 'Претеглена карта, използвана от всеки интервюиращ (тежестите се нормализират до 100 %). Променяйте внимателно — съществуващите карти пазят запазените си оценки.',
