'et.d_s_rc_general' => "Вашата кандидатура {no} — {title} — Golden A/S",
'et.d_s_rc_shortlisted' => "Вашата кандидатура за {title} — следваща стъпка — Golden A/S",
'et.d_s_rc_interview' => "Покана за интервю — {title} — Golden A/S",
'et.d_s_rc_offer' => "Оферта — {title} — Golden A/S",
'et.d_s_rc_rejected' => "Вашата кандидатура за {title} — Golden A/S",
'et.d_b_rc_general' => "Уважаеми/а {name},\n\nБлагодарим Ви за кандидатурата {no} за позицията {title} ({doc}).\n\n\n\nС уважение,\n{user}\n{branch}",
'et.d_b_rc_shortlisted' => "Уважаеми/а {name},\n\nБлагодарим Ви за кандидатурата за позицията {title}. Разгледахме я с интерес и бихме искали да Ви поканим на следващата стъпка от процеса на подбор.\n\nЩе се свържем с Вас скоро, за да уговорим удобно време. Междувременно ни уведомете, ако има промяна във Вашата наличност.\n\nС уважение,\n{user}\n{branch}",
'et.d_b_rc_interview' => "Уважаеми/а {name},\n\nВъв връзка с кандидатурата Ви за позицията {title} бихме искали да Ви поканим на интервю.\n\nДата и час: \nПродължителност: \nФормат / място: \nИнтервюиращи: \n\nМоля, потвърдете, че предложеното време е удобно за Вас, или предложете алтернатива.\n\nС уважение,\n{user}\n{branch}",
'et.d_b_rc_offer' => "Уважаеми/а {name},\n\nС удоволствие Ви съобщаваме, че след процеса на подбор за позицията {title} бихме искали да Ви предложим ролята.\n\nОфициалната оферта с условията на назначение е приложена / ще последва отделно. Моля, разгледайте я и ни уведомете за решението си до .\n\nОчакваме с нетърпение да Ви посрещнем в екипа.\n\nС уважение,\n{user}\n{branch}",
'et.d_b_rc_rejected' => "Уважаеми/а {name},\n\nБлагодарим Ви за кандидатурата за позицията {title} и за времето, което отделихте на нашия процес на подбор.\n\nСлед внимателно разглеждане решихме да продължим с други кандидати, чийто профил е по-близък до изискванията на тази роля. Ще запазим данните Ви за шест месеца и ще се свържем с Вас, ако се открие подходяща позиция.\n\nПожелаваме Ви успех.\n\nС уважение,\n{user}\n{branch}",
'rc.key_once_hint' => 'Копирайте го сега в secret PORTAL_RC_KEY (или PORTAL_STATS_KEY) на хранилището на сайта — при следващо зареждане е маскиран.',
// R91-003 outgoing mail
'web.mail' => 'Outgoing e-mail',
'web.mail_smtp' => 'Authenticated SMTP via {host} as {user} — candidate, HR and website messages pass SPF/DMARC.',
'web.mail_phpmail' => 'PHP mail() — not configured for SMTP. goldenas.com.gr mail is on Microsoft 365 and its SPF rejects other senders: messages will land in junk.',
'web.mail_hint' => 'Предпочитано: Microsoft Graph с OAuth2 client credentials — задайте блока graph в customer/app/config.php (tenant, client_id, client_secret, from) от Entra регистрация на приложение с разрешение Mail.Send, ограничено до изпращащата кутия чрез application access policy; не се съхранява парола. Резервен вариант: блокът smtp (smtp.office365.com:587, кутия с "Authenticated SMTP" и app password). Сайтът използва същите стойности в api/config.php.',
